// Cloud Account & Multi-Device Real-Time Database Synchronization Engine
import { getDatabase, saveDatabase } from "./api.js";
import { showToast } from "../components/Toast.js";

const CLOUD_KEY_STORAGE = "akaun_amanah_cloud_key";
export const DEFAULT_CLOUD_KEY = "KKSP-AMANAH-2026";

let isSyncing = false;
let autoSyncInterval = null;
let lastSyncedTimestamp = null;

/**
 * Get current active Cloud Account Sync Key
 */
export function getCloudSyncKey() {
  return localStorage.getItem(CLOUD_KEY_STORAGE) || DEFAULT_CLOUD_KEY;
}

/**
 * Save new Cloud Account Sync Key
 */
export function setCloudSyncKey(key) {
  const cleanKey = (key || "").trim().toUpperCase() || DEFAULT_CLOUD_KEY;
  localStorage.setItem(CLOUD_KEY_STORAGE, cleanKey);
  return cleanKey;
}

/**
 * Push local database to Cloud Storage
 */
export async function pushDatabaseToCloud() {
  const cloudKey = getCloudSyncKey();
  const db = getDatabase();
  const timestamp = new Date().toISOString();
  db.last_synced = timestamp;

  const payload = {
    cloud_key: cloudKey,
    updated_at: timestamp,
    device_id: window.navigator.userAgent.slice(0, 30),
    db: db,
  };

  try {
    // 1. Save to local key vault cache
    localStorage.setItem(`cloud_vault_${cloudKey}`, JSON.stringify(payload));
    lastSyncedTimestamp = timestamp;

    // 2. Sync to online Cloud REST endpoint
    const url = `https://api.myjson.online/v1/records/${cloudKey.toLowerCase().replace(/[^a-z0-9]/g, "")}`;
    await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    }).catch(() => {});
  } catch (e) {
    console.warn("Cloud push notice:", e);
  }
}

/**
 * Pull latest Database from Cloud Storage (Auto-detects if Cloud has newer data)
 */
export async function pullDatabaseFromCloud(keyInput = null, forceManual = false) {
  if (isSyncing) return { success: false };
  isSyncing = true;

  const cloudKey = keyInput ? setCloudSyncKey(keyInput) : getCloudSyncKey();
  const currentDb = getDatabase();
  const currentTimestamp = currentDb.last_synced || "2000-01-01T00:00:00.000Z";

  try {
    const url = `https://api.myjson.online/v1/records/${cloudKey.toLowerCase().replace(/[^a-z0-9]/g, "")}`;
    const res = await fetch(url);
    if (res.ok) {
      const data = await res.json();
      const cloudPayload = data.data || data;
      if (cloudPayload && cloudPayload.db && cloudPayload.updated_at) {
        const cloudTime = new Date(cloudPayload.updated_at).getTime();
        const localTime = new Date(currentTimestamp).getTime();

        // If Cloud data is newer or user manually requested sync
        if (cloudTime > localTime || forceManual) {
          lastSyncedTimestamp = cloudPayload.updated_at;

          // Save cloud DB locally without re-triggering recursive push
          cloudPayload.db.last_synced = cloudPayload.updated_at;
          localStorage.setItem("akaun_amanah_db_v1", JSON.stringify(cloudPayload.db));
          localStorage.setItem(`cloud_vault_${cloudKey}`, JSON.stringify(cloudPayload));

          showToast(forceManual ? "✓ Data berjaya diselaraskan dari Cloud!" : "☁️ Data dikemaskini secara automatik dari Cloud (PC Kawan)");
          if (window.appRefreshUI) window.appRefreshUI();
          isSyncing = false;
          return { success: true, db: cloudPayload.db, source: "Pelayan Awan (Online Cloud)" };
        }
      }
    }
  } catch (e) {
    console.warn("Online cloud pull notice:", e);
  }

  // Fallback to local vault cache if available
  const cachedVault = localStorage.getItem(`cloud_vault_${cloudKey}`);
  if (cachedVault) {
    try {
      const parsed = JSON.parse(cachedVault);
      if (parsed && parsed.db && forceManual) {
        localStorage.setItem("akaun_amanah_db_v1", JSON.stringify(parsed.db));
        if (window.appRefreshUI) window.appRefreshUI();
        isSyncing = false;
        return { success: true, db: parsed.db, source: "Penyimpanan Tempatan (Vault)" };
      }
    } catch (e) {}
  }

  isSyncing = false;
  return { success: false, source: "Data Sedia Ada" };
}

/**
 * Start Real-Time Automatic Cloud Synchronization Engine (Polls every 6 seconds)
 */
export function initAutoCloudSync() {
  if (autoSyncInterval) clearInterval(autoSyncInterval);

  // Poll cloud every 6 seconds
  autoSyncInterval = setInterval(() => {
    pullDatabaseFromCloud(null, false);
  }, 6000);

  // Also pull immediately whenever tab/window gets focus
  window.addEventListener("focus", () => {
    pullDatabaseFromCloud(null, false);
  });
}
